+// API keys and roles. Keys live in the data as apiKeys: [{ key, name, role }].
+// viewer may only read; cook may also do the day-to-day kitchen work (routes
+// marked "cook"); manager may do everything.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles and their rank; a higher rank may do everything a lower one may. */
+export const ROLES = Object.freeze({ viewer: 1, cook: 2, manager: 3 });
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The apiKeys entry for `key`; throws `unauthorized` when missing or unknown. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const given = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), given)) found ??= k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The role a route needs: its own, else viewer for GET and manager for the rest. */
+export function requiredRole(method, declared) {
+  return declared ?? (method === "GET" ? "viewer" : "manager");
+}
+
+/** Throws `forbidden` unless the key's role reaches `role`. */
+export function authorize(apiKey, role) {
+  const need = ROLES[role];
+  const have = Object.hasOwn(ROLES, apiKey.role) ? ROLES[apiKey.role] : 0;
+  if (need === undefined || have < need) throw new AppError("forbidden");
+}
